      if(!selectedImage.moderatedTags.includes(tagId)){
        selectedImage.moderatedTags.push(tagId)
        modelUpdate({ voteParams: { "imageId": selectedImage.id, "tagId": tagId, "vote": 10}})
      } else {
        selectedImage.moderatedTags = selectedImage.moderatedTags.filter(id => id !== tagId);
        modelUpdate({ voteParams: { "imageId": selectedImage.id, "tagId": tagId, "vote": -10}})
      }

      triggerQuery(model.VoteTagQuery)

      modelUpdate({ images: updatedImages })
    }



    const handleAgeRatingChange = (selectedAgeRating) => {
    if (model.selectedAgeRating !== selectedAgeRating) {
      modelUpdate({ selectedAgeRating });
      triggerQuery(model.setAge);
    }};

    const handleSubmit = () => triggerQuery(model.LogTimestamp)

    const handleModalOpen = () => triggerQuery(model.OpenModal);


    const toggleCategory = () => {
      if(model.expandedCategories.includes("adult")){
        modelUpdate({ expandedCategories: ["violence", "extra"]});
      } else {
        modelUpdate({ expandedCategories: ["adult", "suggestive"]});
      }

    }

    const toggleLabel = (imageId, label) => {

      const updatedImages = [...model.images];
      const selectedImage = updatedImages.find(i => i.id === imageId)

      //if(selectedImage.nsfwlevel === label){
        //return
      //}

      selectedImage.nsfwlevel = label
      modelUpdate({ labelParams: { "imageId": selectedImage.id, "nsfwLevel": label}})

      triggerQuery(model.UpdateNsfwQuery)
      triggerQuery(model.InsertModQuery)
      // triggerQuery(model.InsertRatingGame)

      modelUpdate({ images: updatedImages })
    }

    const handleLabelCheckboxChange = () => {
      modelUpdate({ showLabels: !model.showLabels })
    };

    const handleTagCheckboxChange = () => {
      modelUpdate({ showTags: !model.showTags })
    };

    const [showLabel, setShowLabel] = React.useState(true)
    const handleLabelShow = () => {
      setShowLabel(!showLabel);
}

    const [showTag, setShowTag] = React.useState(true)
    const handleTagShow = () => {
      setShowTag(!showTag)
    }

    const [displayStyle, setDisplayStyle] = React.useState(true)
    const handleDisplayStyle = () => {
      setDisplayStyle(!displayStyle)
    }


return(
<div className="card">
  <div className="header">
    <div className="display-options-container">
      <div className="display-option">
        <label htmlFor="tags">Show Tags</label>
        <input type="checkbox" name="tags" checked={showTag} onChange={handleTagShow} />
      </div>
      <div className="display-option">
        <label htmlFor="labels">Show Ratings</label>
        <input type="checkbox" name="labels" checked={showLabel} onChange={handleLabelShow} />
      </div>
      <div className="display-option">
        <label htmlFor="style">Vertical Style</label>
        <input type="checkbox" name="style" checked={displayStyle} onChange={handleDisplayStyle} />
      </div>
    </div>
    <div className="header-info">
    <p>{model.lastUsedBy[0].username} used the button {humanizeTime(calculateMinutesAgo())} ago</p>
    </div>
    <div>
      <button className="refresh-button" onClick={() => triggerQuery(model.Refresh)}>
        Refresh
      </button>
    </div>
    <div className="age-rating-buttons">
          {model.browsingLabels.map((i) => (
            <button
              key={i.label}
              className={`age-rating-button ${model.selectedAgeRating == i.key ? 'selected' : ''}`}
              onClick={() => handleAgeRatingChange(i.key)}
              title={i.description}
            >
              {i.label}
            </button>

          ))}
    </div>
    <div className="query-filter">
      <select
        onChange={(e) => {
          const selectedValue = e.target.value;
          if (selectedValue === 'newest') {
            modelUpdate({ selectedFilter: "Newest"})
            triggerQuery(model.setFilter)
          } else if (selectedValue === 'reactions') {
            modelUpdate({ selectedFilter: "Reaction"})
            triggerQuery(model.setFilter)
          } 
        }}
      >
        <option value="newest">Newest</option>
        <option value="reactions">Reactions</option>
      </select>
    </div>
  </div>

  <div className="content">
  {model.images.map((image, index) => (
    <div className={`grid-cell ${displayStyle ? 'grid-regular' : 'grid-lars'}`} 
          key={image.id} 
    >
      <div className="label-container">
        <div className="browsing-cells">
          { showLabel && model.browsingLabels.map((i) => {
            return (

              <div className="browsing-button-wrapper" key={i.key}>
                <button 
                  className={`browsing-button ${image.nsfwlevel == i.key ? 'selected-label' : ''} ${image.ainsfwlevel == i.key ? 'ai-nsfwlevel' : ''}`}
                  onClick={() => toggleLabel(image.id, i.key)}
                >
                  {i.label}
                </button>
              </div>
            );
          })}
        </div>
        <div className="image-cell">
          <div className={`image-container ${enlargedImage === index ? 'enlarged' : ''}`}>
            {image.url.endsWith('.mp4') || image.url.endsWith('.webm') ? (
              <video
                width="300"
                controls
                onClick={() => toggleImageEnlarge(index)}
                onMouseLeave={handleMouseLeave}
              >
                <source src={image.url}/>
                Your browser does not support the video tag.
              </video>

            ) : (
                <img
                  src={image.url}
                  width="300px"
                  alt="Maybe video, click me"
                  onClick={() => toggleImageEnlarge(index)}
                  onMouseLeave={handleMouseLeave}
                  title={image.Prompt ? image.Prompt : "No prompt data available"}
                />
            )}
            <button
              className="image-link-button"
              onClick={(e) => {
                e.preventDefault();
                window.open(`https://civitai.com/images/${image.id}`, '_blank');
              }}
            >
              Civit
            </button>
            {image.needsReview && (
              <div className="review-box">
                {image.needsReview}
              </div>
            )}
            {image.profilePictureId && (
              <div className="profile-box">
                Profile Picture
              </div>
            )}
            {image.isBounty && (
              <div className="bounty-box">
                Bounty Picture
              </div>
            )}
          </div>
        </div>
      </div>
      <div className={`categories ${displayStyle ? 'categories-regular' : 'categories-lars'}`}>
        {showTag && model.tagData.categories.map((category) => (
          <div key={category.name} className={`category-name ${category.name}`}>
            {category.tags.map((tag) => {
              if (model.expandedCategories.includes(category.name)) {
                return (
                  <div className="tag-container" key={tag.id}>
                    <button
                      className={hasModTag(tag.id, index)}
                      onClick={() => toggleTag(tag.id, index)}
                    >
                      {tag.name}
                    </button>
                  </div>
                );
              }
            })}
          </div>
        ))}
      </div>
    </div>
  ))}
</div>
  <div className="button-container">
    <div>
      <button
        className="side-button submit-button"
        onClick={() => handleSubmit()}
        disabled={model.images === undefined || model.images.length === 0 || model.selectedFilter === "Reaction"}
      >
        Log
      </button>
    </div>
    <div>
      <button
        className="side-button category-toggle"
        onClick={() => toggleCategory()}
      >
        Toggle
      </button>
    </div>
</div>
</div>
  );}

  // This is the entrypoint for the React component.
  const ConnectedComponent = Retool.connectReactComponent(MyCustomComponent)
  const container = document.getElementById('react')
  const root = ReactDOM.createRoot(container)
  root.render(<ConnectedComponent />)
</script>
